import{_ as e,o as a,c as d,a2 as r}from"./chunks/framework.CmvPqeTF.js";const u=JSON.parse('{"title":"终端使用","description":"","frontmatter":{},"headers":[],"relativePath":"guide/terminal.md","filePath":"guide/terminal.md","lastUpdated":1788361893000}'),o={name:"guide/terminal.md"};function l(i,t,h,n,s,c){return a(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="终端使用" tabindex="-1">终端使用 <a class="header-anchor" href="#终端使用" aria-label="Permalink to &quot;终端使用&quot;">​</a></h1><p>vShell 的终端基于 <a href="https://xtermjs.org/" target="_blank" rel="noreferrer">xterm.js v6</a>，每个会话一个完整的 PTY 终端（<code>xterm-256color</code>），以标签页组织。</p><hr><h2 id="_1-标签页" tabindex="-1">1. 标签页 <a class="header-anchor" href="#_1-标签页" aria-label="Permalink to &quot;1. 标签页&quot;">​</a></h2><p>主区右侧为标签页式终端区（<code>NTabs</code> 卡片风格）：</p><ul><li>标签标题左侧的状态点：<strong>绿色 = 已连接</strong>，灰色 = 已断开</li><li>编辑器标签（<a href="./editor.html">远程文件编辑</a>）与终端标签混排，带 <code>[远端]</code> / <code>[本地]</code> 前缀；未保存时标题后出现橙色 <code>•</code>，悬停显示完整路径</li><li>标签内容常驻内存（隐藏而非销毁），切换标签不丢终端状态</li></ul><h3 id="标签右键菜单" tabindex="-1">标签右键菜单 <a class="header-anchor" href="#标签右键菜单" aria-label="Permalink to &quot;标签右键菜单&quot;">​</a></h3><table tabindex="0"><thead><tr><th>菜单项</th><th>说明</th></tr></thead><tbody><tr><td>复制会话</td><td>基于同一连接再开一个终端会话</td></tr><tr><td>重新连接</td><td>仅断开态可用</td></tr><tr><td>断开连接</td><td>仅连接态可用</td></tr><tr><td>关闭 / 关闭其他 / 关闭所有</td><td>批量关闭</td></tr></tbody></table><h3 id="关闭的两种语义" tabindex="-1">关闭的两种语义 <a class="header-anchor" href="#关闭的两种语义" aria-label="Permalink to &quot;关闭的两种语义&quot;">​</a></h3><table tabindex="0"><thead><tr><th>入口</th><th>行为</th></tr></thead><tbody><tr><td>标签 ✕ / 右键菜单</td><td>只断开<strong>该会话</strong>；若这是所属连接的最后一个终端，同时关闭其 SFTP 面板</td></tr><tr><td><code>⌘W</code>（File → Close）</td><td><strong>断开整条连接</strong>（全部会话 + 监控 + SFTP）并关闭标签</td></tr></tbody></table><h2 id="_2-终端交互" tabindex="-1">2. 终端交互 <a class="header-anchor" href="#_2-终端交互" aria-label="Permalink to &quot;2. 终端交互&quot;">​</a></h2><table tabindex="0"><thead><tr><th>操作</th><th>行为</th></tr></thead><tbody><tr><td>右键</td><td>先选中光标处单词，再弹出菜单：<strong>复制 / 粘贴 / 全选 / 清屏</strong></td></tr><tr><td>复制</td><td>有选区时可用；快捷键见下表</td></tr><tr><td>粘贴</td><td>粘贴到终端（<code>term.paste</code>）</td></tr><tr><td>断线后按回车</td><td><strong>立即重连</strong>：显示「正在重连...」，成功后原标签接续新会话；失败显示「重连失败，按回车键重试」</td></tr><tr><td>双击标题栏</td><td>窗口最大化 / 还原</td></tr></tbody></table><p>断开时终端内显示黄色提示行 <code>--- 连接已断开，按回车键重连 ---</code>。</p><h3 id="复制粘贴快捷键" tabindex="-1">复制粘贴快捷键 <a class="header-anchor" href="#复制粘贴快捷键" aria-label="Permalink to &quot;复制粘贴快捷键&quot;">​</a></h3><table tabindex="0"><thead><tr><th>平台</th><th>复制</th><th>粘贴</th></tr></thead><tbody><tr><td>macOS</td><td><code>⌘C</code>（有选区时）</td><td><code>⌘V</code></td></tr><tr><td>Windows / Linux</td><td><code>Ctrl+Shift+C</code></td><td><code>Ctrl+Shift+V</code></td></tr></tbody></table><p>快捷键可在<a href="./settings.html">设置</a>中自定义。</p><p><strong>终端内 <code>Ctrl+C</code> / <code>Ctrl+V</code> 永远透传给远端</strong>（SIGINT / quoted-insert 语义），不会被应用截走——这是有意设计。</p><h3 id="剪贴板实现" tabindex="-1">剪贴板实现 <a class="header-anchor" href="#剪贴板实现" aria-label="Permalink to &quot;剪贴板实现&quot;">​</a></h3><p>复制 / 粘贴优先走 Wails 运行时剪贴板（macOS WKWebView 下 <code>navigator.clipboard</code> 不可靠），失败时自动回退浏览器 API（问题记录见 <code>docs/issues/0004</code>）。</p><h2 id="_3-渲染与配色" tabindex="-1">3. 渲染与配色 <a class="header-anchor" href="#_3-渲染与配色" aria-label="Permalink to &quot;3. 渲染与配色&quot;">​</a></h2><ul><li><strong>WebGL 渲染</strong>（WebglAddon），不支持时自动回退 canvas 渲染</li><li>光标闪烁开启；右键自动选中单词</li><li><strong>7 套配色</strong>：默认（跟随明暗主题自动切换 dark / light 两套）、Solarized 暗色 / 浅色、Dracula、Monokai、One Dark，在<a href="./settings.html">设置 → 终端</a>中选择，实时生效</li><li>终端字体（Menlo / JetBrains Mono / Fira Code 等）与字号（10–24）同样在设置中调整，实时生效</li></ul><h2 id="_4-窗口尺寸与-pty" tabindex="-1">4. 窗口尺寸与 PTY <a class="header-anchor" href="#_4-窗口尺寸与-pty" aria-label="Permalink to &quot;4. 窗口尺寸与 PTY&quot;">​</a></h2><ul><li>会话建立时以 24 行 × 80 列请求 PTY，随后按窗口实际尺寸 <code>WindowChange</code> 跟随调整</li><li>侧栏拖宽 / 窗口缩放时终端自动重新 fit</li></ul><h2 id="_5-当前边界-如实说明" tabindex="-1">5. 当前边界（如实说明） <a class="header-anchor" href="#_5-当前边界-如实说明" aria-label="Permalink to &quot;5. 当前边界（如实说明）&quot;">​</a></h2><ul><li><strong>终端内搜索（Ctrl+F）未提供</strong></li><li><strong>分屏未提供</strong>（单标签单终端）</li><li><code>⌘W</code> 会断开整条连接（含其他终端会话），关闭单个标签请用标签 ✕</li></ul><hr><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li><a href="./../dev/terminal-io.html">终端 I/O 数据流</a> —— 输入输出如何经 Wails Events 流转</li><li><a href="./settings.html">设置与主题</a> —— 字体、配色、快捷键</li></ul>',28)])])}const m=e(o,[["render",l]]);export{u as __pageData,m as default};
